import pandas as pd

df = pd.read_excel('nces_digest_public_school_enrollment_by_state.xlsx', sheet_name='Digest 2023 Table 203.20', header=None)

col_2022 = None
for r in range(5):
    for c in df.columns:
        if 'Fall 2022' in str(df.iloc[r, c]):
            col_2022 = c
            break
    if col_2022 is not None:
        break

tx_mask = df[0].astype(str).str.strip().str.lower() == 'texas'
tx_row = df[tx_mask].index[0]
result = int(df.iloc[tx_row, col_2022])
